function inlandMapMarkup(){const i=state.inland,ready=inlandReady(state),done=i.kiln&&!i.kiln.left;const pin=(p,name,status,station)=>`<button class="map-pin inland-pin" style="left:${p.x}%;top:${p.y}%" ${station?`data-station="${station}"`:'data-action="go-inland"'} aria-label="${name}: ${status}"><span class="pin-icon">${resourceIcon(station==='claypit'?'clay':station==='preserving'?'preserves':station==='kiln'?'jars':'fruit')}</span><span>${name}<small>${status}</small></span></button>`;return `<svg class="inland-crops" viewBox="0 0 1536 1024" aria-hidden="true"><defs>${INLAND_PLOTS.map(p=>`<clipPath id="crop-clip-${p.id}"><polygon points="${p.polygon}"/></clipPath>`).join('')}</defs>${INLAND_PLOTS.map((p,n)=>i.terraces[n]&&!i.terraces[n].left?inlandCropMarkup(p,i.terraces[n].type):'').join('')}</svg>${done?[INLAND_KILN,INLAND_PRESERVING].map(p=>`<div class="inland-built" style="clip-path:${p.builtClip}" aria-hidden="true"></div>`).join(''):''}${INLAND_PLOTS.map((p,n)=>{const t=i.terraces[n];return pin(p,t?TERRACE_TYPES[t.type].name:(n?'Lower':'Upper')+' terrace',!ready?'Path needed':!t?'Choose crop':t.left?'Planting':'Harvests available',t&&!t.left?'terrace'+n:null)+(t?.left?`<div class="market-work" style="left:${p.x}%;top:${p.y+8}%"><span class="work-frame"></span><small data-inland-time="terrace${n}"></small></div>`:'');}).join('')}${pin(INLAND_CLAY,'Clay bank',ready?'Gather clay':'Path needed',ready?'claypit':null)}${pin(INLAND_KILN,'Pottery kiln',!i.kiln?'Available to build':i.kiln.left?'Under construction':'Jars & tiles',done?'kiln':null)}${done?pin(INLAND_PRESERVING,'Preserving room','Package your harvest','preserving'):''}${i.kiln?.left?`<div class="market-work" style="left:${INLAND_KILN.x}%;top:${INLAND_KILN.y+10}%"><span class="work-frame"></span><small data-inland-time="kiln"></small></div>`:''}<div class="inland-kiln-smoke" style="left:${INLAND_KILN.chimney.x/1536*100}%;top:${INLAND_KILN.chimney.y/1024*100}%" hidden aria-hidden="true"></div><svg class="inland-activity" viewBox="0 0 1536 1024" aria-hidden="true">${['claypit','terrace0','terrace1','kiln','preserving','crew'].map(st=>`<g data-inland-worker="${st}" visibility="hidden"><ellipse cy="9" rx="9" ry="4" fill="#28382e" opacity=".3"/><path d="M-3 7V0h6v7" stroke="#504c3d" stroke-width="3"/><path d="M-5 0V-10h10V0" fill="#788678"/><circle cy="-15" r="5" fill="#d1b68a"/><rect x="3" y="-8" width="8" height="6" fill="#af8d5c"/></g>`).join('')}</svg>`;}
function updateInlandWorkers(){const i=state.inland;$$('[data-inland-worker]').forEach(el=>{const st=el.dataset.inlandWorker,working=st==='crew'?(i.left||i.kiln?.left||i.terraces.some(t=>t?.left)):state.jobs.some(j=>RECIPES[j.key].station===st);el.setAttribute('visibility',working?'visible':'hidden');if(!working)return;const route=INLAND_ROADS[({claypit:'clay',terrace0:'west',terrace1:'east',kiln:'kiln',preserving:'preserving',crew:'arrival'})[st]],phase=(state.seconds/8)%2,t=phase>1?2-phase:phase,segment=Math.min(route.length-2,Math.floor(t*(route.length-1))),a=route[segment],b=route[segment+1],f=t*(route.length-1)-segment;el.setAttribute('transform',`translate(${a[0]+(b[0]-a[0])*f},${a[1]+(b[1]-a[1])*f})`);});}
